INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-FM-002','SUPERMARKET_SHELVER','BASE_ABILITY','FINE_MOTOR',NULL,'OFFLINE_OPERATION','SCORED_ITEM',1,'{"schema_version": "question-content-v1.2", "question_type": "OFFLINE_OPERATION", "prompt": "工具夹持：标准操作盒：安全夹、软球8个、双杯。", "assessment_point": "软件拖拽不能测出夹具开合和真实握力。", "offline_tool_brief": "标准操作盒：安全夹、软球8个、双杯。", "rubric_criteria": [{"criterion_id": "c1", "label": "工具夹持"}, {"criterion_id": "c2", "label": "工具夹持"}]}','{"scoring_type": "OFFLINE_RUBRIC", "criteria": [{"criterion_id": "c1", "description_0": "无法操作夹具或全程无效夹取。", "description_1": "完成不足半数或夹具控制明显不稳。", "description_2": "完成8个软球夹取，错误不超过2次。"}, {"criterion_id": "c2", "description_0": "夹取后全部落球或无法放入杯中。", "description_1": "超过3个落球或需教师协助放入。", "description_2": "不超过2个落球，双杯分别归位。"}]}',NULL,NULL,0,NULL,'ACTIVE',1);
INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-FM-003','SUPERMARKET_SHELVER','BASE_ABILITY','FINE_MOTOR',NULL,'OFFLINE_OPERATION','SCORED_ITEM',1,'{"schema_version": "question-content-v1.2", "question_type": "OFFLINE_OPERATION", "prompt": "旋转操作：标准操作盒：两个空塑料瓶，统一松紧度。", "assessment_point": "软件旋转手势不能替代瓶身稳定和真实阻力。", "offline_tool_brief": "标准操作盒：两个空塑料瓶，统一松紧度。", "rubric_criteria": [{"criterion_id": "c1", "label": "旋转操作"}, {"criterion_id": "c2", "label": "旋转操作"}]}','{"scoring_type": "OFFLINE_RUBRIC", "criteria": [{"criterion_id": "c1", "description_0": "无法握持瓶身或完全无旋转动作。", "description_1": "完成1瓶以下或方向反复错误。", "description_2": "两瓶均完成开合，无明显滑脱。"}, {"criterion_id": "c2", "description_0": "全程单手或瓶身持续倾斜。", "description_1": "偶尔双手配合，拧合不到位超过2次。", "description_2": "双手配合稳定，拧合力度适当。"}]}',NULL,NULL,0,NULL,'ACTIVE',1);
INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-FM-004','SUPERMARKET_SHELVER','BASE_ABILITY','FINE_MOTOR',NULL,'OFFLINE_OPERATION','SCORED_ITEM',1,'{"schema_version": "question-content-v1.2", "question_type": "OFFLINE_OPERATION", "prompt": "双手配合：标准操作盒：预印中线A5卡纸2张。", "assessment_point": "触屏折叠不能测出双手固定和纸张控制。", "offline_tool_brief": "标准操作盒：预印中线A5卡纸2张。", "rubric_criteria": [{"criterion_id": "c1", "label": "双手配合"}, {"criterion_id": "c2", "label": "双手配合"}]}','{"scoring_type": "OFFLINE_RUBRIC", "criteria": [{"criterion_id": "c1", "description_0": "无法对折或纸张完全位移。", "description_1": "完成对折但中线偏差超过1厘米。", "description_2": "中线对齐偏差在5毫米内，折痕清晰。"}, {"criterion_id": "c2", "description_0": "单手完成或另一手未起固定作用。", "description_1": "双手参与但固定手持续滑动。", "description_2": "双手分工明确，固定手稳定不滑动。"}]}',NULL,NULL,0,NULL,'ACTIVE',1);
INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-FM-006','SUPERMARKET_SHELVER','BASE_ABILITY','FINE_MOTOR',NULL,'OFFLINE_OPERATION','SCORED_ITEM',1,'{"schema_version": "question-content-v1.2", "question_type": "OFFLINE_OPERATION", "prompt": "穿引操作：标准操作盒：大孔珠5颗、加固绳端粗软绳。", "assessment_point": "软件目标拖拽不能替代双手穿引和深度控制。", "offline_tool_brief": "标准操作盒：大孔珠5颗、加固绳端粗软绳。", "rubric_criteria": [{"criterion_id": "c1", "label": "穿引操作"}, {"criterion_id": "c2", "label": "穿引操作"}]}','{"scoring_type": "OFFLINE_RUBRIC", "criteria": [{"criterion_id": "c1", "description_0": "无法穿入任何珠子。", "description_1": "穿入不足3颗或需教师协助引导绳端。", "description_2": "5颗全部穿入，绳端自行引导完成。"}, {"criterion_id": "c2", "description_0": "完成后绳端散开或珠子脱落。", "description_1": "绳端固定不稳，1—2颗脱落。", "description_2": "绳端固定完好，无珠子脱落。"}]}',NULL,NULL,0,NULL,'ACTIVE',1);
INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-FM-012','SUPERMARKET_SHELVER','BASE_ABILITY','FINE_MOTOR',NULL,'OFFLINE_OPERATION','SCORED_ITEM',2,'{"schema_version": "question-content-v1.2", "question_type": "OFFLINE_OPERATION", "prompt": "持物稳定与移动：共用低成本器材：轻质托盘、3个塑料空杯、地面标线。", "assessment_point": "软件无法测量真实持物稳定、步态和动态平衡。", "offline_tool_brief": "共用低成本器材：轻质托盘、3个塑料空杯、地面标线。", "rubric_criteria": [{"criterion_id": "c1", "label": "持物稳定与移动"}, {"criterion_id": "c2", "label": "持物稳定与移动"}]}','{"scoring_type": "OFFLINE_RUBRIC", "criteria": [{"criterion_id": "c1", "description_0": "无法端起托盘或行走不足1米。", "description_1": "完成但空杯倒落超过2个或明显偏离标线。", "description_2": "空杯全部保持，沿标线完成3米行走。"}, {"criterion_id": "c2", "description_0": "全程跌跌撞撞或借助支撑物。", "description_1": "步态基本稳定但1次明显失衡。", "description_2": "步态稳定，无借助支撑物。"}]}',NULL,NULL,0,NULL,'ACTIVE',1);
